import{z as s,x as i,o as e,c as n,q as t,j as l,D as a,d as A,s as o,S as r}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"ToT 与 MCTS 的工程化","description":"","frontmatter":{"title":"ToT 与 MCTS 的工程化","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/pl-tot-mcts-engineering.md","filePath":"llm/pl-tot-mcts-engineering.md","lastUpdated":1791063341000}'),p={name:"llm/pl-tot-mcts-engineering.md"};function m(d,E,C,T,h,c){const B=i("Mermaid");return e(),n("div",null,[E[2]||(E[2]=t('<h1 id="tot-与-mcts-的工程化" tabindex="-1">ToT 与 MCTS 的工程化 <a class="header-anchor" href="#tot-与-mcts-的工程化" aria-label="Permalink to &quot;ToT 与 MCTS 的工程化&quot;">​</a></h1><div class="epigraph"><p>论文里的搜索伪代码搬进服务，最先撞上的不是算法，而是显存、延迟与账单：树长得越漂亮，每次前向烧得越快。</p><footer>—— 据 Yao et al., Tree of Thoughts, NeurIPS 2023；Kocsis &amp; Szepesvári, UCT, 2006；Hao et al., RAP, 2023 整理</footer></div><p><a href="/llm/rag-map">上一课</a>把 RAG 系统收进「症状到三角角度、角度到层、层到旋钮」的排查协议，检索增强的深钻交了卷。回到单次生成，best-of-n 是成本-质量曲线末端的最后一档：同一提示开 \\(N\\) 条完整链，在终点挑一条。缺口在于 \\(N\\) 条链彼此独立、每条都走到底，钱花在注定要扔的完整前缀上；要回溯、要在中间状态上比较与剪枝，就得把搜索树搬进服务。本课写 <a href="/llm/tree-of-thoughts">ToT</a> 与 <a href="/llm/mcts-llm">MCTS</a> 从论文 demo 到线上服务的工程化：节点怎么表示、树由谁持有、KV 怎么复用、每次前向的钱怎么记账。后课的过程监督、反思与预算分配默认以本课的树形服务为底座。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>ToT 论文里的 Game of 24 与填字是单机脚本：一棵树、几十次模型调用、跑完即弃。同一算法放进服务，问题换成另一组三件套。第一，节点是什么：一个节点对应一段部分解答，动作若切到 token 级，分支因子就是词表大小，树在第二层就爆炸；切到步骤级才有可剪枝的分叉，而步骤怎么切是任务定义，换切分等于换一棵树。第二，树由谁持有：模型只看到当前节点的上下文，树本身必须由编排层持有——节点表、父子边、分数、终态标记；模型不给树，宿主不给上下文，搜索退化成普通对话。第三，账单单位是节点数不是请求数：扩展一个节点要一次生成前向（提议 \\(k\\) 个后继），打分要一次评估前向或一次 PRM 调用。</p><p>MCTS 的四步循环在语言模型上每一步都有工程语义：选择按 \\(\\mathrm{UCT}=\\bar Q+c\\sqrt{\\ln N_p/N_c}\\) 在节点间配额；扩展用模型提议步骤级后继；评估给出节点价值；回传更新祖先的 \\(\\bar Q\\)。注意这是冻结策略加外部价值的测试时搜索，不是 AlphaZero 式的自我对弈；搜索轨迹要改进权重，必须另走蒸馏或 RL。</p><p><span class="marginnote">直觉类比：UCT 像决定今晚去哪家馆子——常去且好评的店（\\(\\bar Q\\) 高）与还没试过几次的新店（\\(N_c\\) 低）之间权衡，\\(c\\) 就是「想尝新」的强度：调太大天天踩雷，调太小永远只吃同一家，好店永远 discovery 不到。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>树的持有与 KV 复用决定系统能否成立。兄弟节点共享同一前缀，若每个节点都完整重算 prefill，树搜索比独立采样还贵；按<a href="/llm/prefix-caching">前缀缓存</a>组织 KV，新节点只为增量段算一次，扩展才便宜。深 \\(d\\)、分支 \\(b\\) 的完全树有 \\(O(b^d)\\) 个节点，预算必须写成显式闸门：最大深度、最大分支、节点总数、墙钟时间，四个同时生效，任一触发就回传当前最优叶。</p><p><span class="marginnote">分支 \\(b=5\\)、深度 \\(d=6\\) 的完全树约 \\(1.9\\) 万个节点；按每节点两次前向计，一个请求就是近 4 万次前向。工程上从不长完全树：UCT 配额与终态剪枝把实际节点数压进预算，超出即降级。</span></p><p>服务侧由此把「一个请求」变成「一片异步负载」：分支节点扇出、叶节点终止，有的请求三个节点出解，有的烧满预算。批处理要按节点入队而不是按请求串行，否则先到的树堵住后面的请求；返回给用户的仍是完整的一条链——树是内擎，外交还是普通文本流。</p>',11)),(e(),l(r,null,{default:a(()=>[o(B,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ROOT%5B%22%E6%8E%A5%E6%94%B6%E8%AF%B7%E6%B1%82%EF%BC%8C%E5%BB%BA%E6%A0%B9%E8%8A%82%E7%82%B9%22%5D%20--%3E%20SEL%5B%22%E9%80%89%E6%8B%A9%EF%BC%9A%E6%8C%89%20UCT%20%E6%8C%91%E8%8A%82%E7%82%B9%22%5D%0A%20%20SEL%20--%3E%20EXP%5B%22%E6%89%A9%E5%B1%95%EF%BC%9A%E6%8F%90%E8%AE%AE%20k%20%E4%B8%AA%E6%AD%A5%E9%AA%A4%E7%BA%A7%E5%90%8E%E7%BB%A7%22%5D%0A%20%20EXP%20--%3E%20EVAL%5B%22%E8%AF%84%E4%BC%B0%EF%BC%9A%E8%87%AA%E8%AF%84%20%2F%20PRM%20%2F%20%E7%BB%88%E5%B1%80%E6%A8%A1%E6%8B%9F%22%5D%0A%20%20EVAL%20--%3E%20BACK%5B%22%E5%9B%9E%E4%BC%A0%EF%BC%9A%E6%9B%B4%E6%96%B0%E7%A5%96%E5%85%88%20Q%22%5D%0A%20%20BACK%20--%3E%20BUD%7B%22%E9%A2%84%E7%AE%97%E9%97%B8%E9%97%A8%E8%A7%A6%E5%8F%91%3F%22%7D%0A%20%20BUD%20--%3E%7C%E5%90%A6%7C%20SEL%0A%20%20BUD%20--%3E%7C%E6%98%AF%7C%20RET%5B%22%E5%9B%9E%E4%BC%A0%E6%9C%80%E4%BC%98%E5%8F%B6%EF%BC%8C%E8%BE%93%E5%87%BA%E5%8D%95%E6%9D%A1%E9%93%BE%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>树搜索改变的是预算的形状，不是模型的概率。同一批推理 FLOPs，花在宽度（\\(N\\) 条独立链）上覆盖不同假设，花在深度（树上回溯）上修正同一假设的中途错误；二者不可互相替代，这正是<a href="/llm/test-time-scaling">测试时计算</a>里按难度配策略的物理基础。评估器决定剪枝方向：自评最便宜也最弱，搜索会朝流畅的假推理走；PRM 与 lookahead 终局模拟更硬，但每次评估都要前向，<a href="/llm/prm-guided-search">过程奖励引导的搜索</a>的校准问题在服务里被放大成账单问题——评估器不准，钱烧得越急，错得越整齐。</p><p><span class="marginnote">数字实例：评估不是免费的——一棵 \\(1{,}000\\) 节点的树，每节点评估一次、每次评估输入约 \\(2{,}000\\) token，仅打分就是约 \\(200\\) 万 token 的账单。评估器换一档（自评换 PRM），钱的变化比准确率的变化先到。</span></p>',3)),(e(),l(r,null,{default:a(()=>[o(B,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E5%90%8C%E4%B8%80%E6%89%B9%E6%8E%A8%E7%90%86%E9%A2%84%E7%AE%97%22%5D%20--%3E%20W%5B%22%E5%AE%BD%E5%BA%A6%EF%BC%9AN%20%E6%9D%A1%E7%8B%AC%E7%AB%8B%E5%AE%8C%E6%95%B4%E9%93%BE%22%5D%0A%20%20F%20--%3E%20D%5B%22%E6%B7%B1%E5%BA%A6%EF%BC%9A%E4%B8%80%E6%A3%B5%E5%8F%AF%E5%9B%9E%E6%BA%AF%E7%9A%84%E6%A0%91%22%5D%0A%20%20W%20--%3E%20W1%5B%22%E5%90%84%E8%B5%B0%E5%88%B0%E5%BA%95%EF%BC%8C%E7%BB%88%E7%82%B9%E6%8C%91%E6%9C%80%E5%A5%BD%22%5D%0A%20%20W%20--%3E%20W2%5B%22%E8%B5%B7%E7%82%B9%E5%B0%B1%E9%94%99%EF%BC%9A%E6%95%B4%E6%9D%A1%E4%BD%9C%E5%BA%9F%22%5D%0A%20%20D%20--%3E%20D1%5B%22%E4%B8%AD%E9%80%94%E8%AF%84%E4%BC%B0%EF%BC%8C%E9%94%99%E5%8D%B3%E5%89%AA%E6%9E%9D%E5%9B%9E%E6%BA%AF%22%5D%0A%20%20D%20--%3E%20D2%5B%22%E4%BB%A3%E4%BB%B7%EF%BC%9A%E6%AF%8F%E6%AD%A5%E5%A4%9A%E4%BB%98%E8%AF%84%E4%BC%B0%E5%89%8D%E5%90%91%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>延迟敏感的在线请求大多付不起一棵树，应退回 <a href="/llm/best-of-n">Best-of-N</a> 或<a href="/llm/self-consistency">自洽</a>，把树留给离线与高价值场景。探索常数 \\(c\\) 不能直接抄棋类：过大即是昂贵的随机采样，过小则整棵树长在第一条被采样的分支上。开放域没有可靠终局核对时，收益上限被评估器钉死。树搜索也不自动等于更强：很难的题目上搜索补不齐预训练缺失的知识，烧满预算只是烧满，不是答对。</p><p><span class="marginnote">常见误区：初学者容易以为「上了搜索就一定更准」。实际上搜索只能在模型已有的能力上挑路——预训练里根本没见过的知识，树长得再大也变不出来，烧满预算只是烧满。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>账单单位是节点：扩展一次生成前向、评估一次打分前向；深度、分支、节点数、时间四个闸门必须显式设。</li><li>动作切到步骤级才有可搜索的分支因子；宿主持有树，模型只见当前节点的上下文。</li><li>KV 前缀复用让兄弟节点只算增量；批处理按节点入队，对外仍交付单条链。</li><li>冻结策略加外部价值不是自我对弈；搜索轨迹要进权重需另做蒸馏或 RL。</li><li>评估器校准决定搜索上限；延迟敏感场景退回 BoN 或自洽。</li><li>出处：Yao et al., <em>Tree of Thoughts</em>, NeurIPS 2023；Kocsis &amp; Szepesvári, UCT, 2006；Hao et al., RAP, 2023；Snell et al., 2024。</li></ul>',5))])}const f=s(p,[["render",m]]);export{D as __pageData,f as default};
